using System;using System.IO;using System.Linq;using System.Globalization;using System.Collections.Generic;using System.Xml;using BeamScheduleFormatter;
class PowRefinementTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,string why){Check(Math.Abs(a-b)<1e-7,why);}static void Reject(Action action,string why){bool failed=false;try{action();}catch{failed=true;}Check(failed,why);}
 static void Main(){var cfg=new LengthConfiguration{Name="Column sample",GradeSmall=40,GradeLarge=60,FySmall=275,FyLarge=420,Input=new LengthInput{Fc=28,Round=25,Simplified=true}};
 var column=MiscStructureTakeoff.Member("Column Estimate","C1","Sample mixed main bars",3,400,600,2,40,20,4,16,8,10,"Spacing (mm)",150,50,400,false,0,cfg);var bars=column.Steel.Result.Lines.Where(l=>l.Part.StartsWith("Column longitudinal")).ToList();Check(bars.Count==2&&bars.Any(l=>l.Diameter==20&&l.PiecesPerBeam==4)&&bars.Any(l=>l.Diameter==16&&l.PiecesPerBeam==8),"Both screenshot main bar groups retained independently");double before=column.Steel.Result.Total;int stations=column.Steel.Result.Lines.Single(l=>l.Part=="Stirrups").TieSetsPerBeam;ColumnOpenTies.Add(column,400,600,40,10,2,1,"135° / 135°",cfg);var width=column.Steel.Result.Lines.Single(l=>l.Part=="Column open ties / Width");var depth=column.Steel.Result.Lines.Single(l=>l.Part=="Column open ties / Depth");Check(width.PiecesPerBeam==stations*2&&depth.PiecesPerBeam==stations,"Open pieces counted per station independently for each direction");Check(width.CutLength<depth.CutLength,"Width/depth lengths follow actual rectangular column dimensions");Near(width.Metres,width.CutLength*stations*2*2,"Open width tie metres include column multiplicity exactly once");Near(depth.Metres,depth.CutLength*stations*2,"Open depth tie metres include column multiplicity exactly once");Near(column.Steel.Result.Total,before+width.Kg+depth.Kg,"Main closed tie retained and extra pieces added once");var plan=CommercialBars.Allocate(new[]{column.Steel},cfg,new[]{6.0});Check(plan.Count(a=>a.Line==width)>0&&plan.Count(a=>a.Line==depth)>0,"Both open shapes included in stock purchase planning");Reject(()=>ColumnOpenTies.Add(column,400,600,40,10,1,0,"Select hook angles",cfg),"Open hook geometry must be explicitly selected");Check(ColumnTieSchedule.Count("1 - 50mm, 11 - 75mm, AND REST AT 200mm C/C (3 TIES/SET)",3,400,600,10,40,cfg)==ColumnTieSchedule.Count("1 - 50mm, 11 - 75mm, REST AT 200mm C/C",3,400,600,10,40,cfg),"3 ties/set note does not invent additional pieces");Check(ColumnTieSchedule.Count("1 - 50mm, AND REST AT 75mm C/C",3,400,600,10,40,cfg)==40,"Uniform sample column tie schedule counted between actual end offsets");
 Check(EarthworkPayRouting.Code("Gravel|TOTAL GRAVEL TO BUY","TOTAL GRAVEL TO BUY","m3")=="804(7)","Beam/footing gravel purchase explicitly routes to 804(7)");Check(EarthworkPayRouting.Code("Earthworks|Embankment FROM EXCAVATION - loose material","Embankment FROM EXCAVATION - loose material","cu.m.")=="804(1)a","Embankment from excavation explicitly routes to 804(1)a");Check(EarthworkPayRouting.Code("Earthworks|Embankment FROM COMMON BORROW","Embankment FROM COMMON BORROW - loose material to buy","m3")=="804(2)a","Borrow remains a separate target");Check(EarthworkPayRouting.Code("Slope Protection Works|Foundation Fill","Foundation Fill","m3")==null,"Slope foundation fill keeps its existing 103(3) route");
 var ranges=Enumerable.Range(1,266).Select(i=>"BC"+(i*12)+":BC"+(i*12+9)).ToList();Check(string.Join(",",ranges.Take(32)).Length>255,"Old fixed 32-range batch reproduces Excel address limit violation");var batches=ExcelRangeBatches.Pack(ranges).ToList();Check(batches.All(b=>b.Length<=200)&&batches.SelectMany(b=>b.Split(',')).SequenceEqual(ranges),"New Excel batches preserve every detail range within address limit");foreach(var value in new object[]{300,"300","16","8","150",0,75m,.4})Check(QuantityInputDefaults.IsNumber(value),"Numeric measurement defaults recognized: "+value);Check(!QuantityInputDefaults.IsNumber("Spacing (mm)"),"Non-numeric input method remains a selectable default");
 string dir=Path.Combine(Path.GetTempPath(),"DTCE-atomic-save-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"Project.pow.xml");PowProjectFileWriter.AtomicWrite(path,"first");PowProjectFileWriter.AtomicWrite(path,"second");Check(File.ReadAllText(path)=="second","Atomic save replaces the full existing file");Reject(()=>PowProjectFileWriter.AtomicWrite(Path.Combine(dir,"missing","Project.pow.xml"),"failed"),"Failed file write surfaces an error");Check(File.ReadAllText(path)=="second"&&Directory.GetFiles(dir,"*.tmp").Length==0,"Failed save leaves prior file and no temporary residue");}finally{Directory.Delete(dir,true);}Console.WriteLine("PASS: "+checks+" mixed-main-bar, open-tie, pay routing, Excel batching, blank-input and atomic-save checks");}
}
